figures.script:
diagram("direction: right
[Source 1] as a #blue
[Source 2] as b #mint
[Source 3] as c #amber
[Multiplexer] as m #violet
[One shared link] as l #grey
[Demultiplexer] as d #violet
a -> m
b -> m
c -> m
m -> l
l -> d
@0 a -> m : slot 1
@1 b -> m : slot 2
@2 c -> m : slot 3
@3 m -> l : frame
@4 l -> d : frame
loop 6");
